import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String order = next();
        int n = nextInt();
        int[] rank = new int[128];
        for (int i = 0; i < order.length(); i++) rank[order.charAt(i)] = i;
        // Sort key: each character replaced by its rank, so String.compareTo follows the custom order.
        String[] values = new String[n], keys = new String[n];
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) {
            String s = next();
            if (s.equals("-")) s = "";
            char[] key = new char[s.length()];
            for (int j = 0; j < key.length; j++) key[j] = (char) rank[s.charAt(j)];
            values[i] = s;
            keys[i] = new String(key);
            idx[i] = i;
        }
        Arrays.sort(idx, (x, y) -> keys[x].compareTo(keys[y]));
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String s = values[idx[i]];
            sb.append(s.isEmpty() ? "-" : s).append(i + 1 < n ? ' ' : '\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	order := readToken()
	n := readInt()
	var rank [256]byte
	for i := 0; i < len(order); i++ {
		rank[order[i]] = byte(i)
	}
	// Sort key: each character replaced by its rank, so plain string comparison follows the custom order.
	type item struct{ key, value string }
	items := make([]item, n)
	for i := range items {
		s := readToken()
		if s == "-" {
			s = ""
		}
		key := make([]byte, len(s))
		for j := 0; j < len(s); j++ {
			key[j] = rank[s[j]]
		}
		items[i] = item{string(key), s}
	}
	sort.Slice(items, func(a, b int) bool { return items[a].key < items[b].key })
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, it := range items {
		if it.value == "" {
			w.WriteString("-")
		} else {
			w.WriteString(it.value)
		}
		if i+1 < n {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
